"use strict";
/* ==========================================================================
   微光摄影社 · 投稿水印（数据万象 CI，仅服务端）
   审核通过时把水印「打进」公开图片，双层设计：
     第 1 步（保证据）：公开原图原样复制到 _original/ 私有前缀（桶策略拒匿名读，
        由用户在控制台配置）。原图 + EXIF 是版权证据，绝不覆盖。
        ⚠️ 已存在则跳过——重试时绝不拿已打水印的图反过来覆盖真原图。
     第 2 步（打水印）：以 _original/ 为源做持久化处理（POST image_process +
        Pic-Operations），输出 fileid=公开 key 覆盖原文件——URL 不变，前台代码
        零改动，任何人下载拿到的都是带水印版。
   水印内容 = 站点 logo 图（内嵌 base64，首次自动上传 COS wm/ 目录，右下角、
        原尺寸、无边距——logo 已预缩 350px 宽并带细暗描边，浅色照片上也可见）
        + 盲水印（纯盲文字，肉眼不可见、抗裁剪压缩，可用 CI 提取验证权属）。
   开关（Vercel 环境变量）：
     CI_IMAGE_WATERMARK=0  退回纯文字水印（logo 方案异常时兜底）
     CI_BLIND_WATERMARK=0  去掉盲水印（未开通盲水印功能时兜底）
     WATERMARK_TEXT / WATERMARK_BLIND_TEXT  覆盖默认文案
   ========================================================================== */

var cos = require("./cos");

var WM_KEY = "wm/glimmer-mark.png";
var WM_IMAGE_B64 = "";
var WM_TEXT = process.env.WATERMARK_TEXT || "微光摄影社 · GLIMMER";
var ORIGINAL_PREFIX = "_original/";

/* CI 规则参数里的 base64 一律用 URL 安全变体（+/ → -_），避免 / 冲断路径段 */
function b64u(s) {
  return Buffer.from(String(s), "utf8").toString("base64url");
}

function wmUrl() {
  return "https://" + cos.hostOf() + "/" + WM_KEY;
}

/* 处理规则：可见水印（logo 图，右下角无边距）| 盲水印（纯盲文字）。
   管道符 | 按顺序串联，一次处理出一张图。 */
function buildRule() {
  var ops = [];
  if (process.env.CI_IMAGE_WATERMARK === "0") {
    /* 兜底：纯文字水印（与站点设计一致的白字 + 透明度） */
    ops.push("watermark/2/text/" + b64u(WM_TEXT) +
      "/font/" + b64u("simhei") +
      "/fontsize/30/fill/" + b64u("FFFFFFB4") +
      "/dissolve/72/gravity/southeast/margin/24");
  } else {
    ops.push("watermark/1/image/" + b64u(wmUrl()) + "/gravity/southeast");
  }
  if (process.env.CI_BLIND_WATERMARK !== "0") {
    var blind = process.env.WATERMARK_BLIND_TEXT || "GLIMMER 柳铁一中微光摄影社";
    ops.push("watermark/3/type/3/text/" + b64u(blind));
  }
  return ops.join("|");
}

/* 首次使用自举：把内嵌 logo 传到 COS（公开读——CI 取水印图要用，且 logo 无保密性） */
async function ensureLogo() {
  if (await cos.objectExists(WM_KEY)) return;
  await cos.putBuffer(WM_KEY, Buffer.from(WM_IMAGE_B64, "base64"), "image/png");
}

/* 公开 key → 私有原图 key */
function originalKeyOf(publicKey) {
  return ORIGINAL_PREFIX + publicKey;
}

/* 审核通过时调用；也可对已发布作品重试。返回 { ok, originalKey } 或抛错 */
async function applyWatermark(publicKey) {
  await ensureLogo();
  var oKey = originalKeyOf(publicKey);
  if (!(await cos.objectExists(oKey))) {
    await cos.copyObject(publicKey, oKey); /* 第一步永远是保原图 */
  }
  await cos.imageProcess(oKey, publicKey, buildRule()); /* 处理结果覆盖公开位 */
  return { ok: true, originalKey: oKey };
}

module.exports = {
  applyWatermark: applyWatermark,
  buildRule: buildRule,
  originalKeyOf: originalKeyOf,
  ensureLogo: ensureLogo,
  WM_KEY: WM_KEY,
  WM_TEXT: WM_TEXT,
  ORIGINAL_PREFIX: ORIGINAL_PREFIX
};
